      SUBROUTINE RDLOOK(KWORD,LWORD,KDICT,IDICT1,IDICT2,IDICT)C---- FIND WORD "KWORD" OF LENGTH "LWORD" IN DICTIONARY "KDICT"C-------------------------------------------------------------------      CHARACTER*15    KDICT(*), KWORDC-------------------------------------------------------------------      CHARACTER*15      KTEMP, BLANK      DATA BLANK        /' '/C-------------------------------------------------------------------C      IDICS = 0      IF (IDICT1 .EQ. 0) GO TO 20      IF (IDICT1 .GT. IDICT2) GO TO 20      L = MAX0(4,LWORD)      DO 10 IDIC = IDICT1, IDICT2        IF (IDICS .NE. 0 .AND. IDIC .GT. IDICS + 20) GO TO 20        KTEMP = KDICT(IDIC)(1:L)        IF (KWORD .EQ. KTEMP) THEN          LENG = 4          DO 5 LL = 5, 8          IF (KDICT(IDIC)(LL:LL) .EQ. BLANK) GO TO 6          LENG = LL    5     CONTINUE    6     IF (L .EQ. LENG) GO TO 30          IF (IDICS .EQ. 0) IDICS = IDIC        ENDIF   10 CONTINUE   20 IDICT = 0      IF (IDICS .NE. 0) IDICT = IDICS      GO TO 50C   30 IDICT = IDICC   50 RETURN      END